Rule.Source:
      
      import org.apache.commons.logging.Log;
      import org.apache.commons.logging.LogFactory;

      import sailpoint.object.Identity;
      import sailpoint.object.Link;
      import sailpoint.object.Application;
      import sailpoint.api.IdentityService;
      import sailpoint.api.PasswordGenerator;
      import sailpoint.object.ProvisioningPlan;
      import sailpoint.object.ProvisioningPlan.AccountRequest;
      import sailpoint.object.ProvisioningPlan.AttributeRequest;
      import sailpoint.provisioning.ApplicationPolicyExpander;

      Log log = LogFactory.getLog("sailpoint.rule.WF_CreateADPasswordPlan");

      // Name of AD Application to change password for
      String AD_APPLICATION = "ADDirectDemoData";

      // get Identity out of wfContext
      // String identityName = wfContext.get("identityName");
      log.debug("identityName: " + identityName);
      if (identityName == null) {
        log.error("Cannot generate plan with null identityName");
        return null;
      }

      Identity identity = context.getObjectByName(Identity.class, identityName);
      if (identity == null) {
        log.error(identityName + " was not found");
        return null;
      }

      Application application = context.getObjectByName(Application.class, AD_APPLICATION);
      if (application == null) {
        log.error(AD_APPLICATION + " was not found");
        return null;
      }

      IdentityService idSvc = new IdentityService(context);
      List<Link> links = idSvc.getLinks(identity, application);

      PasswordGenerator genny = new PasswordGenerator(context);
      ProvisioningPlan plan = new ProvisioningPlan();

      // if more than one Link was found, we'll build a password plan for each
      for (Link link : links) {
          log.debug("next Link: " + link);

          AccountRequest newAcctReq = new AccountRequest();
          newAcctReq.setApplication(link.getApplicationName());
          newAcctReq.setNativeIdentity(link.getNativeIdentity());
          newAcctReq.setOperation(AccountRequest.Operation.Modify);
          newAcctReq.put(ApplicationPolicyExpander.PROVISIONING_POLICIES, 
                Collections.singletonList(ApplicationPolicyExpander.CHANGE_PASSWORD_POLICY));
          plan.add(newAcctReq);

          AttributeRequest attr = new AttributeRequest();
          attr.setName("password");
          attr.setOperation(ProvisioningPlan.Operation.Set);
          attr.setValue(context.encrypt(genny.generatePassword(link)));
          newAcctReq.add(attr);

          attr = new AttributeRequest(attr);
          attr.setName("pwdLastSet");
          attr.setValue(true);
          newAcctReq.add(attr);
      }
      if (log.isDebugEnabled()) {
        log.debug("Returning plan: " + plan.toXml());
      }

      return plan;
